SELECT COUNT(*) FROM material_task t
JOIN material_order o ON o.id = t.order_id AND o.deleted = 0
WHERE t.status = #{status}

SELECT COUNT(*) FROM material_task t
JOIN material_order o ON o.id = t.order_id AND o.deleted = 0
WHERE t.assignee_id = #{assigneeId} AND t.status = #{status}
